with open('/app/resources/treasury_bulletin_1982_03_page_44.txt', 'r') as f:
    content = f.read()

# Parse the HTML table
class TableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_th = False
        self.in_td = False
        self.rows = []
        self.current_row = []
        self.current_cell = ""

    def handle_starttag(self, tag, attrs):
        if tag == 'tr':
            self.current_row = []
        elif tag in ['th', 'td']:
            self.in_th = (tag == 'th')
            self.in_td = (tag == 'td')
            self.current_cell = ""

    def handle_endtag(self, tag):
        if tag in ['th', 'td']:
            if self.in_th or self.in_td:
                self.current_cell = self.current_cell.strip()
                self.current_row.append(self.current_cell)
        if tag == 'tr' and self.current_row:
            self.rows.append(self.current_row)

    def handle_data(self, data):
        if self.in_th or self.in_td:
            self.current_cell += data

parser = TableParser()
parser.feed(content)

# The table shows TWO parts - left for current year, right for subsequent years
# Let's examine specifically - extract ONLY 1982 section (first section before "1983" year header)

# Find the index of "1983" section to know where 1982 ends
current_section = None
section_starts = {}

for i, row in enumerate(parser.rows):
    if len(row) >= 1:
        first_col = row[0].strip()
        # Check if it's a year header (4-digit year)
        if first_col.isdigit() and len(first_col) == 4:
            current_section = first_col
            section_starts[current_section] = i

print(f"Section starts: {section_starts}")

# 1982 section runs from index 2 (header) to before 1983 section
if '1982' in section_starts and '1983' in section_starts:
    start_idx = section_starts['1982']
    end_idx = section_starts['1983']
    print(f"\n1982 section runs from index {start_idx} to {end_idx-1}")

    print("\n1982 section entries:")
    print("-" * 80)
    total_1982 = 0
    for i in range(start_idx, end_idx):
        row = parser.rows[i]
        if len(row) >= 4:
            first_col = row[0].strip()
            total_str = row[3] if len(row) > 3 else ""

            # Skip year header row and total row
            if first_col == '1982':
                continue
            if first_col == '' and total_str == '':
                continue

            # Check if data row (has date format with ....)
            if '....' in first_col:
                if total_str and total_str not in ['*', '–', '']:
                    try:
                        total_val = int(total_str.replace(',', ''))
                        print(f"{first_col:15} {row[1][:25]:25} Total: {total_val:,}")
                        total_1982 += total_val
                    except:
                        print(f"{first_col:15} {row[1][:25]:25} Total: {total_str} (skipped)")
            elif 'Total' in row[1]:
                print(f"{'TOTAL':15} {row[1]:25} Total: {total_str}")

    print("-" * 80)
    print(f"Total nominal maturities for CY 1982: ${total_1982:,} million")
